// TestCreateValidationHTTP sends requests the API refuses before any job is
// queued.
func (s *APIPublicTestSuite) TestCreateValidationHTTP() {
	s.api.Run(s.T(), []servertest.Case{
		{
			Name: "when the target is not an agent, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/nowhere/user/osapitest/sshkey",
				Body:   `{"name":"osapitest","key":"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJl85dcLw7lIdX+IyXEXT00CTCezv/2E1jvolleleo6Z osapitest@example"}`,
			},
			Token:    servertest.Admin,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when the target is empty, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node//user/osapitest/sshkey",
				Body:   `{"name":"osapitest","key":"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJl85dcLw7lIdX+IyXEXT00CTCezv/2E1jvolleleo6Z osapitest@example"}`,
			},
			Token:    servertest.Admin,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when key is missing, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/user/osapitest/sshkey",
				Body:   `{"name":"osapitest","key":""}`,
			},
			Token:    servertest.Admin,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when the body is not JSON, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/user/osapitest/sshkey",
				Body:   `{`,
			},
			Token:    servertest.Admin,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when key has the wrong type, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/user/osapitest/sshkey",
				Body:   `{"key":[]}`,
			},
			Token:    servertest.Admin,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when sent a name that is not a user name, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/user/Bad%3Bname/sshkey",
				Body:   `{"name":"Bad;name","key":"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJl85dcLw7lIdX+IyXEXT00CTCezv/2E1jvolleleo6Z osapitest@example"}`,
			},
			Token:    servertest.Admin,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when sent a name over 32 characters, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/user/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/sshkey",
				Body:   `{"name":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","key":"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJl85dcLw7lIdX+IyXEXT00CTCezv/2E1jvolleleo6Z osapitest@example"}`,
			},
			Token:    servertest.Admin,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when sent a key with a line break, it is a 400",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/user/osapitest/sshkey",
				Body:   `{"name":"osapitest","key":"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJl85dcLw7lIdX+IyXEXT00CTCezv/2E1jvolleleo6Z osapitest@example\nssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIGLPeEZQDbhOrSIx6gISjxXIcREV3rwL517pX6m9G5jc other@example"}`,
			},
			Token:    servertest.Admin,
			WantCode: http.StatusBadRequest,
		},
	})
}

// TestCreateRBACHTTP sends tokens that do not grant user:write.
func (s *APIPublicTestSuite) TestCreateRBACHTTP() {
	s.api.Run(s.T(), []servertest.Case{
		{
			Name: "when there is no token, it is a 401",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/user/osapitest/sshkey",
				Body:   `{"name":"osapitest","key":"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJl85dcLw7lIdX+IyXEXT00CTCezv/2E1jvolleleo6Z osapitest@example"}`,
			},
			Token:    servertest.NoToken,
			WantCode: http.StatusUnauthorized,
		},
		{
			Name: "when the token lacks user:write, it is a 403",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/user/osapitest/sshkey",
				Body:   `{"name":"osapitest","key":"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJl85dcLw7lIdX+IyXEXT00CTCezv/2E1jvolleleo6Z osapitest@example"}`,
			},
			Token:    servertest.Lacking,
			WantCode: http.StatusForbidden,
		},
		{
			Name: "when the token has only the read role, it is a 403",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/user/osapitest/sshkey",
				Body:   `{"name":"osapitest","key":"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJl85dcLw7lIdX+IyXEXT00CTCezv/2E1jvolleleo6Z osapitest@example"}`,
			},
			Token:    servertest.Read,
			WantCode: http.StatusForbidden,
		},
		{
			Name: "when the token has the write role, it is a 403: the method is admin only",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/user/osapitest/sshkey",
				Body:   `{"name":"osapitest","key":"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJl85dcLw7lIdX+IyXEXT00CTCezv/2E1jvolleleo6Z osapitest@example"}`,
			},
			Token:    servertest.Write,
			WantCode: http.StatusForbidden,
		},
		{
			Name: "when the token has the admin role, the request runs",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/user/osapitest/sshkey",
				Body:   `{"name":"osapitest","key":"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJl85dcLw7lIdX+IyXEXT00CTCezv/2E1jvolleleo6Z osapitest@example"}`,
			},
			Token: servertest.Admin,
			Job: servertest.Modify(
				"server1",
				"sshkey.create",
				sshkey.CreateInput{
					Key:  "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJl85dcLw7lIdX+IyXEXT00CTCezv/2E1jvolleleo6Z osapitest@example",
					Name: "osapitest",
				},
				servertest.Skipped("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"unsupported","hostname":"server1","status":"skipped"}]}`,
		},
	})
}

